export default {"html":"<p data-line=\"0\" class=\"code-line\">This article is part of the <a href=\"https://adventar.org/calendars/5963\" target=\"_blank\" rel=\"noopener noreferrer\">Ionic Framework / Capacitor Advent Calendar 2020</a>.</p>\n<p data-line=\"2\" class=\"code-line\"><img src=\"https://static.zenn.studio/user-upload/i2m82kz998ycm9vo6wtzqfd14ep2\" alt=\"\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"4\" class=\"code-line\"><a href=\"https://ionicframework.jp/docs/\" target=\"_blank\" rel=\"noopener noreferrer\">https://ionicframework.jp/docs/</a><br>\n<a href=\"https://ionicframework.com/jp/docs/\" target=\"_blank\" rel=\"noopener noreferrer\">https://ionicframework.com/jp/docs/</a></p>\n<p data-line=\"7\" class=\"code-line\">I added links from Zenn to the Ionic Japan User Group's ionicframework.jp and the Ionic official ionicframework.com jp directory. The links are on <a href=\"https://zenn.dev/topics/ionic\" target=\"_blank\" rel=\"noopener noreferrer\">https://zenn.dev/topics/ionic</a>.</p>\n<p data-line=\"9\" class=\"code-line\">This is an experimental effort, but I hope you will find it useful.</p>\n<h2 id=\"addendum\" data-line=\"11\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#addendum\" aria-hidden=\"true\"></a> <a href=\"#%E8%A3%9C%E8%B6%B3\"></a>Addendum</h2>\n<h2 id=\"what-is-ionic-framework%3F\" data-line=\"13\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-is-ionic-framework%3F\" aria-hidden=\"true\"></a> <a href=\"#ionic-framework%E3%81%A8%E3%81%AF\"></a>What Is Ionic Framework?</h2>\n<p data-line=\"15\" class=\"code-line\">Ionic Framework is a framework for building mobile apps with web technologies. It lets you use the rich expressiveness of HTML/CSS to build web apps and also iOS and Android mobile apps distributed through app stores. Besides loading it with a script tag, it officially supports Angular, React, and Vue.</p>\n<p data-line=\"17\" class=\"code-line\">Overseas, General Electric in the United States (a conglomerate like Sony in Japan) and the UK's National Health Service use it. In Japan, Sumitomo Mitsui Banking Corporation and TechFeed, which recently raised ¥100 million, have adopted it.</p>\n<p data-line=\"19\" class=\"code-line\"><a href=\"https://amzn.to/2JgXV3D\" target=\"_blank\" rel=\"noopener noreferrer\">https://amzn.to/2JgXV3D</a></p>\n","headings":[{"id":"addendum","text":"Addendum","level":2},{"id":"what-is-ionic-framework%3F","text":"What Is Ionic Framework?","level":2}]} as const;
